import pandas as pd
import numpy as np

# Load all available experiments
exps = {}
for i in [1, 4, 5, 7, 9]:
    try:
        df = pd.read_csv(f'experiment_{i}_csv')
        exps[i] = df
        print(f"\n=== Experiment {i} ===")
        print(f"Columns: {list(df.columns)}")
        print(f"Shape: {df.shape}")
        print(df.head(2))
        if 'ConversionEfficiency' in df.columns:
            print(f"Mean ConversionEfficiency: {df['ConversionEfficiency'].mean():.2f}")
    except Exception as e:
        print(f"Error loading experiment {i}: {e}")

